#include "Monstey_NavCompactCooker.hpp"
#include "Monstey_NavSeamMatcher.hpp"
#include "Monstey_Core.hpp"
#include <array>
#include <bit>
#include <cstring>
#include <iostream>
#include <set>
using namespace Monstey;
namespace {
using V=Monstey_NavigationVector4;
struct Mesh {Monstey_Bytes faces,edges,vertices;std::vector<std::int32_t>face_map,edge_map;Monstey_NavigationBoundaryMeshView View()const{Monstey_NavigationBoundaryMeshView out{};out.faces=faces;out.edges=edges;out.vertices=vertices;out.face_map=face_map;out.edge_map=edge_map;out.transform={V{1,0,0,0},V{0,1,0,0},V{0,0,1,0},V{0,0,0,0}};return out;}};
Mesh Room(unsigned count,bool second){Mesh out;out.faces.resize(count*16);out.edges.resize(count*80);out.vertices.resize(count*64);out.face_map.assign(count,-1);out.edge_map.assign(count*4,-1);for(unsigned i=0;i<count;++i){const float x0=static_cast<float>(i*2),x1=x0+2;const std::array<V,4>points=second?std::array<V,4>{V{x1,0,0,0},V{x0,0,0,0},V{x0,0,2,0},V{x1,0,2,0}}:std::array<V,4>{V{x0,0,0,0},V{x1,0,0,0},V{x1,0,-2,0},V{x0,0,-2,0}};Monstey_PutU32(out.faces,i*16,i*4);Monstey_PutU16(out.faces,i*16+8,4);for(unsigned e=0;e<4;++e){const auto offset=(i*4+e)*20;Monstey_PutU32(out.edges,offset,i*4+e);Monstey_PutU32(out.edges,offset+4,i*4+(e+1)%4);Monstey_PutU32(out.edges,offset+8,0xffffffff);Monstey_PutU32(out.edges,offset+12,0xffffffff);std::memcpy(out.vertices.data()+(i*4+e)*16,points[e].data(),16);}}
for(unsigned i=0;i+1<count;++i){const unsigned a=i*4+(second?3:1),b=(i+1)*4+(second?1:3);Monstey_PutU32(out.edges,a*20+8,b);Monstey_PutU32(out.edges,a*20+12,i+1);Monstey_PutU32(out.edges,b*20+8,a);Monstey_PutU32(out.edges,b*20+12,i);}return out;}
}
int wmain(int argc,wchar_t**argv){try{Monstey_Require(argc==2,"NEW_REPORT");unsigned groups=0,total=0;const auto empty=Monstey_NavCookCompactBounds({});Monstey_Require(empty.nodes.empty()&&std::bit_cast<std::uint32_t>(empty.bounds.minimum[0])==0x7f7fffee,"Empty complete cooker output differs");++groups;Monstey_Json sizes=Monstey_Json::array();for(const unsigned count:{1u,2u,3u,17u,32u}){const auto a=Room(count,false),b=Room(count,true);const auto treeA=Monstey_NavCookCompactMesh(a.faces,a.edges,a.vertices),treeB=Monstey_NavCookCompactMesh(b.faces,b.edges,b.vertices);Monstey_Require(treeA.nodes.size()==(count*2-1)*6&&treeB.nodes.size()==treeA.nodes.size(),"New-room compact node count differs");const auto av=a.View(),bv=b.View();const Monstey_NavSeamSettings settings{{.5f,.1f,.01f,.0001f,.9f,.9f,.02f},.9f,.9f};for(const auto flags:std::array<std::array<std::uint8_t,2>,4>{{{0,0},{1,1},{0,1},{1,0}}}){const auto matched=Monstey_NavSeamMatchMeshes(av,bv,treeA.bounds,treeB.bounds,{treeA.nodes,treeA.bounds},{treeB.nodes,treeB.bounds},flags[0],flags[1],V{0,1,0,0},.01f,settings);Monstey_Require(matched.connections.size()==count&&matched.coincident_connections==count,"Cooked authored room seam count differs");std::set<std::uint32_t>faces;for(const auto&connection:matched.connections){Monstey_Require(connection.face_a==connection.face_b&&connection.edge_a==connection.face_a*4&&connection.edge_b==connection.face_b*4,"Cooked room selected wrong original face/edge identity");faces.insert(connection.face_a);}Monstey_Require(faces.size()==count,"Cooked room omitted/duplicated original face");++groups;total+=count;}sizes.as_array().push_back(Monstey_Json::object({{"faces_per_mesh",count},{"compact_nodes_per_mesh",treeA.nodes.size()/6},{"routes",4},{"all_original_boundary_pairs_connected",true}}));}
Monstey_WriteNewText(argv[1],Monstey_Json::object({{"status","PASS"},{"groups",groups},{"connections_checked",total},{"authored_mesh_sizes",sizes},{"supplied_tree_required",false},{"original_program_executed",false},{"runtime_verified",false}}).dump(2)+"\n");std::cout<<"PASS "<<groups<<" cooked new-room seam groups / "<<total<<" connections\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
